function makeState(p, tick) {
  return p.kind === 'bucket' ? { units: p.capacity * p.per, last: tick } : { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const max = p.capacity * p.per
    s.units += p.refill * (tick - s.last)
    if (s.units > max) s.units = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}

function allows(p, s) {
  return p.kind === 'bucket' ? s.units >= p.per : BigInt(s.ticks.length) < p.limit
}

function record(p, s, tick) {
  if (p.kind === 'bucket') s.units -= p.per
  else s.ticks.push(tick)
}

export function simulate(mode, policies, routes, events) {
  const states = new Map()
  const stats = new Map()
  const lines = []
  let allowed = 0
  let denied = 0
  for (const { tick, key } of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let refused = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const id = `${p.name}\0${key}`
        if (!states.has(id)) states.set(id, makeState(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < list.length; i++) {
        if (!allows(list[i], sts[i])) {
          refused = list[i].name
          break
        }
      }
      if (refused === null) list.forEach((p, i) => record(p, sts[i], tick))
    }
    const st = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, st)
    if (refused === null) {
      st.a++
      allowed++
      lines.push(`${tick} ${key} allow`)
    } else {
      st.d++
      denied++
      lines.push(`${tick} ${key} deny ${refused}`)
    }
  }
  if (mode === 'replay') return lines.map((l) => l + '\n').join('')
  const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let out = ''
  for (const k of keys) out += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
